function decorateLambdaPanelHelp(section, root = document) {
  for (const [selector, title, helpKey] of lambdaPanelHelpTargets[section] ?? []) {
    const heading = root.querySelector(`${selector} > .card-header h2`);
    if (!heading || heading.textContent.trim() !== title && !heading.textContent.trim().startsWith(`${title} (`)) continue;
    const meta = heading.querySelector(".muted")?.textContent.trim() ?? "";
    heading.outerHTML = panelHeading(title, lambdaPanelHelp[helpKey], meta);
  }
}

function bytesBase64(bytes) {
  let binary = "";
  for (let index = 0; index < bytes.length; index += 32768) binary += String.fromCharCode(...bytes.subarray(index, index + 32768));
  return btoa(binary);
}

function crc32(bytes) {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

const textEncoder = new TextEncoder();

/** Entries of a ZIP archive, keeping the compressed bytes so untouched files are copied verbatim on deploy. */
function readZipEntries(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength); let eocd = -1;
  for (let index = bytes.length - 22; index >= Math.max(0, bytes.length - 65_557); index--) if (view.getUint32(index, true) === 0x06054b50) { eocd = index; break; }
  if (eocd < 0) throw new Error("The deployment package is not a ZIP archive");
  const count = view.getUint16(eocd + 10, true); let offset = view.getUint32(eocd + 16, true); const entries = [];
  for (let index = 0; index < count; index++) {
    if (view.getUint32(offset, true) !== 0x02014b50) throw new Error("The deployment package central directory is damaged");
    const method = view.getUint16(offset + 10, true); const crc = view.getUint32(offset + 16, true); const compressedSize = view.getUint32(offset + 20, true); const size = view.getUint32(offset + 24, true); const nameLength = view.getUint16(offset + 28, true); const extraLength = view.getUint16(offset + 30, true); const commentLength = view.getUint16(offset + 32, true); const externalAttributes = view.getUint32(offset + 38, true); const localOffset = view.getUint32(offset + 42, true);
    const name = new TextDecoder().decode(bytes.subarray(offset + 46, offset + 46 + nameLength));
    const dataStart = localOffset + 30 + view.getUint16(localOffset + 26, true) + view.getUint16(localOffset + 28, true);
    entries.push({ name, method, crc, size, externalAttributes, raw: bytes.subarray(dataStart, dataStart + compressedSize) });
    offset += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

async function inflateZipEntry(entry) {
  if (entry.method === 0) return entry.raw;
  if (entry.method !== 8) throw new Error(`Unsupported ZIP compression method ${entry.method}`);
  return new Uint8Array(await new Response(new Blob([entry.raw]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).arrayBuffer());
}

function storedZipEntry(name, source) { const data = textEncoder.encode(source); return { name, method: 0, crc: crc32(data), size: data.length, externalAttributes: (0o100644 << 16) >>> 0, raw: data }; }

/** Writes a ZIP from readZipEntries/storedZipEntry entries; timestamps stay zero like the previous single-file writer. */
function buildZip(entries) {
  const names = entries.map(entry => textEncoder.encode(entry.name));
  const localSize = entries.reduce((sum, entry, index) => sum + 30 + names[index].length + entry.raw.length, 0); const centralSize = entries.reduce((sum, entry, index) => sum + 46 + names[index].length, 0);
  const bytes = new Uint8Array(localSize + centralSize + 22); const view = new DataView(bytes.buffer); const offsets = []; let position = 0;
  entries.forEach((entry, index) => { offsets.push(position); view.setUint32(position, 0x04034b50, true); view.setUint16(position + 4, 20, true); view.setUint16(position + 8, entry.method, true); view.setUint32(position + 14, entry.crc, true); view.setUint32(position + 18, entry.raw.length, true); view.setUint32(position + 22, entry.size, true); view.setUint16(position + 26, names[index].length, true); bytes.set(names[index], position + 30); bytes.set(entry.raw, position + 30 + names[index].length); position += 30 + names[index].length + entry.raw.length; });
  const central = position;
  entries.forEach((entry, index) => { view.setUint32(position, 0x02014b50, true); view.setUint16(position + 4, 0x031e, true); view.setUint16(position + 6, 20, true); view.setUint16(position + 10, entry.method, true); view.setUint32(position + 16, entry.crc, true); view.setUint32(position + 20, entry.raw.length, true); view.setUint32(position + 24, entry.size, true); view.setUint16(position + 28, names[index].length, true); view.setUint32(position + 38, entry.externalAttributes ?? ((0o100644 << 16) >>> 0), true); view.setUint32(position + 42, offsets[index], true); bytes.set(names[index], position + 46); position += 46 + names[index].length; });
  view.setUint32(position, 0x06054b50, true); view.setUint16(position + 8, entries.length, true); view.setUint16(position + 10, entries.length, true); view.setUint32(position + 12, centralSize, true); view.setUint32(position + 16, central, true);
  return bytes;
}

function inlineLambdaZipBase64(source, fileName = "index.mjs") { return bytesBase64(buildZip([storedZipEntry(fileName, source)])); }

const handlerExportName = handler => handler.slice(handler.lastIndexOf(".") + 1);
/** index.handler → index.mjs, index.js, index.cjs in the order the Node.js runtime resolves them. */
function handlerFileCandidates(handler) { const dot = handler.lastIndexOf("."); const base = dot > 0 ? handler.slice(0, dot) : handler; return [`${base}.mjs`, `${base}.js`, `${base}.cjs`]; }
const looksLikeCommonJs = source => /\b(?:module\.exports|exports\s*\.\s*[A-Za-z_$]|exports\s*\[)/.test(source) && !/^\s*export\s/m.test(source);
const inlineLambdaFileName = source => looksLikeCommonJs(source) ? "index.js" : "index.mjs";

/** Accepts ES module exports and CommonJS assignments; the exported name must match the handler suffix. */
function validateHandlerSource(source, handler, fileName = "index.mjs") {
  if (!source.trim()) throw new Error("Enter JavaScript code for the function");
  const exportName = handlerExportName(handler);
  if (!exportName || !/^[A-Za-z_$][\w$]*$/.test(exportName)) throw new Error(`Handler ${handler} must end in an exported function name, such as index.handler`);
  const escaped = exportName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const esm = new RegExp(`export\\s+(?:(?:async\\s+)?function\\s*\\*?\\s*${escaped}\\b|(?:const|let|var|class)\\s+${escaped}\\b)|export\\s*\\{[^}]*\\b${escaped}\\b`).test(source);
  const cjs = new RegExp(`(?:module\\.)?exports\\s*\\.\\s*${escaped}\\s*=|module\\.exports\\s*=\\s*\\{[^}]*\\b${escaped}\\b|exports\\s*\\[\\s*["']${escaped}["']\\s*\\]\\s*=`).test(source);
  if (!esm && !cjs) throw new Error(`The code must export ${exportName} to match the ${handler} handler: export const ${exportName} = … (ES module) or exports.${exportName} = … (CommonJS)`);
  if (fileName.endsWith(".mjs") && !esm) throw new Error(`${fileName} is an ES module, so use export const ${exportName} = …; CommonJS code belongs in a .js or .cjs file`);
  if (fileName.endsWith(".cjs") && !cjs) throw new Error(`${fileName} is a CommonJS module, so use exports.${exportName} = …`);
}

function validateInlineLambdaSource(source, handler) {
  if (!/^index\./.test(handler)) throw new Error("Inline code is packaged as index.mjs (ES module) or index.js (CommonJS), so the handler must start with index.");
  validateHandlerSource(source, handler, inlineLambdaFileName(source));
}

/** Public IAM Query API, so roles the console lists or creates are the same ones the IAM console and CLI show. */
async function listIamRoles() {
  const result = await awsQuery("iam", "ListRoles", { MaxItems: 1000 });
  return [...(result.xml?.getElementsByTagName("member") ?? [])].map(node => {
    const value = tag => node.getElementsByTagName(tag)[0]?.textContent ?? "";
    const roleName = value("RoleName"); const arn = value("Arn"); if (!roleName || !arn) return undefined;
    let assumeRolePolicyDocument = {}; try { assumeRolePolicyDocument = JSON.parse(decodeURIComponent(value("AssumeRolePolicyDocument"))); } catch {}
    return { roleName, arn, assumeRolePolicyDocument };
  }).filter(Boolean);
}

async function createBasicExecutionRole(roleName, description, policyArns) {
  const created = await awsQuery("iam", "CreateRole", { RoleName: roleName, Description: description, AssumeRolePolicyDocument: JSON.stringify({ Version: "2012-10-17", Statement: [{ Effect: "Allow", Principal: { Service: "lambda.amazonaws.com" }, Action: "sts:AssumeRole" }] }) });
  for (const policyArn of policyArns) await awsQuery("iam", "AttachRolePolicy", { RoleName: roleName, PolicyArn: policyArn });
  return created.xml?.getElementsByTagName("Arn")[0]?.textContent ?? `arn:aws:iam::${ui.summary?.accountId}:role/${roleName}`;
}

