  async function lambdaCapacityProviderDetail(name) {
    setChrome("lambda", ["Lambda", "Capacity providers", name]); const [result, attached, tagResult] = await Promise.all([rest(`/2025-11-30/capacity-providers/${encodeURIComponent(name)}`), rest(`/2025-11-30/capacity-providers/${encodeURIComponent(name)}/function-versions?MaxItems=50`), rest(`/2017-03-31/tags/${encodeURIComponent(`arn:aws:lambda:${ui.summary.region}:${ui.summary.accountId}:capacity-provider:${name}`)}`)]); const item = result.CapacityProvider; const tags = tagResult.Tags ?? {}; const scaling = item.CapacityProviderScalingConfig ?? {}; const policy = scaling.ScalingPolicies?.[0]; const propagation = item.PropagateTags ?? {}; const logging = item.TelemetryConfig?.LoggingConfig ?? {}; const functions = attached.FunctionVersions ?? [];
    main.innerHTML = `<div class="page-width">${pageHeader(name, item.CapacityProviderArn, `<button class="button" data-copy="${escapeHtml(item.CapacityProviderArn)}">Copy ARN</button><button class="button" data-action="edit-capacity-provider">Edit</button><button class="button danger" data-action="delete-capacity-provider">Delete</button>`)}<div class="alert warning"><strong>Control plane only — no managed infrastructure</strong><br>State transitions and attachments are modeled locally. No compute instances, placement, networking, storage, encryption, or capacity telemetry are created.</div><section class="card capacity-provider-overview-card"><div class="card-header"><h2>Provider overview</h2></div><div class="card-body"><div class="detail-grid"><dl class="key-value"><dt>State</dt><dd><span class="status ${providerStateClass(item.State)}">${escapeHtml(item.State)}</span></dd><dt>Last modified</dt><dd>${formatDate(item.LastModified)}</dd><dt>Operator role</dt><dd class="mono">${escapeHtml(item.PermissionsConfig?.CapacityProviderOperatorRoleArn)}</dd></dl><dl class="key-value"><dt>Architecture</dt><dd>${escapeHtml(item.InstanceRequirements?.Architectures?.join(", ") || "Not constrained")}</dd><dt>Allowed instance types</dt><dd>${escapeHtml(item.InstanceRequirements?.AllowedInstanceTypes?.join(", ") || "–")}</dd><dt>Excluded instance types</dt><dd>${escapeHtml(item.InstanceRequirements?.ExcludedInstanceTypes?.join(", ") || "–")}</dd></dl><dl class="key-value"><dt>Scaling mode</dt><dd>${escapeHtml(scaling.ScalingMode || "Not configured")}</dd><dt>Maximum vCPUs</dt><dd>${scaling.MaxVCpuCount ?? "–"}</dd><dt>CPU target</dt><dd>${policy?.TargetValue ?? "–"}${policy ? "%" : ""}</dd></dl></div></div></section><section class="card capacity-provider-network-card"><div class="card-header"><h2>VPC and telemetry</h2></div><div class="card-body detail-grid"><dl class="key-value"><dt>Subnets</dt><dd class="mono">${escapeHtml(item.VpcConfig?.SubnetIds?.join(", ") || "None")}</dd><dt>Security groups</dt><dd class="mono">${escapeHtml(item.VpcConfig?.SecurityGroupIds?.join(", ") || "None")}</dd></dl><dl class="key-value"><dt>System log level</dt><dd>${escapeHtml(logging.SystemLogLevel || "Default")}</dd><dt>Log group</dt><dd class="mono">${escapeHtml(logging.LogGroup || `/aws/lambda/capacity-provider/${name}`)}</dd><dt>KMS key ARN</dt><dd class="mono">${escapeHtml(item.KmsKeyArn || "Default reference")}</dd></dl><dl class="key-value"><dt>Propagation mode</dt><dd>${escapeHtml(propagation.Mode || "None")}</dd><dt>Explicit tags</dt><dd class="mono">${escapeHtml(JSON.stringify(propagation.ExplicitTags ?? {}))}</dd><dt>Provider tags</dt><dd class="mono">${escapeHtml(JSON.stringify(tags))}</dd></dl></div><div class="card-body"><button class="button" data-action="edit-capacity-tags">Manage provider tags</button></div></section><section class="card capacity-provider-functions-card"><div class="card-header"><div><h2>Attached function versions <span class="muted">(${functions.length}/100)</span></h2><p class="muted small">Mutable and published assignments prevent provider deletion.</p></div></div><div class="table-wrap">${functions.length ? `<table><thead><tr><th>Function version ARN</th><th>State</th></tr></thead><tbody>${functions.map(fn => `<tr><td class="mono">${escapeHtml(fn.FunctionArn)}</td><td><span class="status ${providerStateClass(fn.State)}">${escapeHtml(fn.State)}</span></td></tr>`).join("")}</tbody></table>` : emptyState("λ", "No attached versions", "Assign this active provider from a function's configuration, then publish the function.")}</div></section></div>`;
    document.querySelector('[data-action="edit-capacity-provider"]').addEventListener("click", () => showModal("Edit capacity provider", `<div class="alert warning"><strong>Mutable fields only</strong><br>VPC, operator role, instance requirements, and KMS key are immutable. Updates return to Pending briefly and do not provision resources.</div><div class="field-row"><div class="field"><label>Scaling mode</label><select name="mode"><option value="Auto" ${scaling.ScalingMode !== "Manual" ? "selected" : ""}>Auto</option><option value="Manual" ${scaling.ScalingMode === "Manual" ? "selected" : ""}>Manual</option></select></div><div class="field"><label>Maximum vCPUs</label><input name="maxVcpu" type="number" min="2" max="15000" value="${scaling.MaxVCpuCount ?? 20}" required></div></div><div class="field"><label>CPU target (%)</label><input name="target" type="number" min="0" max="100" value="${policy?.TargetValue ?? 60}" required></div><div class="field"><label>Propagated tags (JSON object)</label><textarea name="propagated">${escapeHtml(JSON.stringify(propagation.ExplicitTags ?? {}, null, 2))}</textarea></div><div class="field-row"><div class="field"><label>System log level</label><select name="level">${["DEBUG", "INFO", "WARN"].map(level => `<option ${level === (logging.SystemLogLevel || "INFO") ? "selected" : ""}>${level}</option>`).join("")}</select></div><div class="field"><label>Log group</label><input name="logGroup" value="${escapeHtml(logging.LogGroup || "")}"></div></div>`, "Save", async data => { const propagated = JSON.parse(String(data.get("propagated") || "{}")); const logGroup = String(data.get("logGroup") || ""); await rest(`/2025-11-30/capacity-providers/${encodeURIComponent(name)}`, "PUT", { CapacityProviderScalingConfig: { ScalingMode: String(data.get("mode")), MaxVCpuCount: Number(data.get("maxVcpu")), ScalingPolicies: [{ PredefinedMetricType: "LambdaCapacityProviderAverageCPUUtilization", TargetValue: Number(data.get("target")) }] }, PropagateTags: Object.keys(propagated).length ? { Mode: "Explicit", ExplicitTags: propagated } : { Mode: "None" }, TelemetryConfig: { LoggingConfig: { SystemLogLevel: String(data.get("level")), ...(logGroup ? { LogGroup: logGroup } : {}) } } }); toast("Capacity provider update started"); }));
    document.querySelector('[data-action="edit-capacity-tags"]').addEventListener("click", () => showModal("Manage capacity provider tags", `<div class="field"><label>Tags (JSON object)</label><textarea name="tags">${escapeHtml(JSON.stringify(tags, null, 2))}</textarea></div>`, "Save", async data => { const next = JSON.parse(String(data.get("tags") || "{}")); const removed = Object.keys(tags).filter(key => !(key in next)); if (removed.length) await rest(`/2017-03-31/tags/${encodeURIComponent(item.CapacityProviderArn)}?${removed.map(key => `tagKeys=${encodeURIComponent(key)}`).join("&")}`, "DELETE"); if (Object.keys(next).length) await rest(`/2017-03-31/tags/${encodeURIComponent(item.CapacityProviderArn)}`, "POST", { Tags: next }); toast("Capacity provider tags updated"); }));
    document.querySelector('[data-action="delete-capacity-provider"]').addEventListener("click", () => confirmDeletion(name, `Delete capacity provider ${name}? Every mutable or published function assignment must be removed first.`, async () => { await rest(`/2025-11-30/capacity-providers/${encodeURIComponent(name)}`, "DELETE"); toast("Capacity provider deletion started"); location.hash = "#/lambda/capacity-providers"; }));
  }

  function layerForm(name) {
    return `<form id="layer-publish-form"><div class="card"><div class="card-header"><div><h2>${name ? "Publish a new version" : "Layer details"}</h2><p class="muted small">Layer ZIP contents are immutable after publishing.</p></div></div><div class="card-body">${name ? `<input type="hidden" name="name" value="${escapeHtml(name)}"><div class="alert info"><strong>${escapeHtml(name)}</strong><br>A new monotonically increasing version will be created.</div>` : '<div class="field"><label>Layer name</label><input name="name" required pattern="[A-Za-z0-9_\\-]+" maxlength="140" placeholder="shared-dependencies"></div>'}<div class="field"><label>Description</label><input name="description" maxlength="256" placeholder="Shared Node.js dependencies"></div><div class="field"><label>License information</label><input name="license" maxlength="512" placeholder="MIT"></div><div class="field"><label>Compatible runtimes</label><div class="checkbox-list"><label><input type="checkbox" name="runtime" value="nodejs24.x"> Node.js 24.x</label><label><input type="checkbox" name="runtime" value="nodejs22.x" checked> Node.js 22.x</label><label><input type="checkbox" name="runtime" value="nodejs20.x"> Node.js 20.x</label><label><input type="checkbox" name="runtime" value="nodejs18.x"> Node.js 18.x</label></div></div><div class="field"><label>Compatible architectures</label><div class="checkbox-list"><label><input type="checkbox" name="architecture" value="x86_64" checked> x86_64</label><label><input type="checkbox" name="architecture" value="arm64"> arm64</label></div></div><div class="field"><label>Layer ZIP file</label><input type="file" name="zip" accept=".zip,application/zip" required><span class="hint">Place Node.js packages under nodejs/node_modules or nodejs/node22/node_modules.</span></div><div class="actions"><a class="button" href="${name ? `#/lambda/layers/${encodeURIComponent(name)}` : "#/lambda/layers"}">Cancel</a><button class="button primary" type="submit">Publish</button></div></div></div></form>`;
  }

  function bindLayerForm() {
    const form = document.querySelector("#layer-publish-form"); form.querySelectorAll("input, select, textarea").forEach(control => control.addEventListener("input", () => setDirty(true, "page"))); form.addEventListener("submit", async event => { event.preventDefault(); const data = new FormData(form); const submit = form.querySelector('button[type="submit"]'); submit.disabled = true; try { const name = String(data.get("name")); const file = data.get("zip"); const result = await rest(`/2018-10-31/layers/${encodeURIComponent(name)}/versions`, "POST", { Description: String(data.get("description") || ""), LicenseInfo: String(data.get("license") || ""), CompatibleRuntimes: data.getAll("runtime"), CompatibleArchitectures: data.getAll("architecture"), Content: { ZipFile: await fileBase64(file) } }); setDirty(false, "page"); toast(`Published ${name}:${result.Version}`); location.hash = `#/lambda/layers/${encodeURIComponent(name)}/versions/${result.Version}`; } catch (error) { submit.disabled = false; showError(error); } });
  }

