      if (fn.CapacityProviderConfig) try { fn.LocalFunctionScalingConfig = await rest(`/2025-11-30/functions/${encodeURIComponent(name)}/function-scaling-config?Qualifier=${encodeURIComponent("$LATEST.PUBLISHED")}`); } catch {}
