    const deliveryGuidance = mappings.some(mapping => isSqsEventSourceArn(mapping.EventSourceArn)) ? "<strong>At-least-once event delivery</strong><br>DynamoDB checkpoints and SQS acknowledgement state advance only after successful handling. Source-specific filters, retries, partial batch responses, and concurrency controls are durable across restart." : "<strong>At-least-once stream delivery</strong><br>Checkpoints advance after successful handling. Filters, partial batch responses, retries, age limits, and bisection are durable across restart.";
    const apiRows = apiTriggers.map(trigger => `<tr><td>${trigger.href ? `<a href="${trigger.href}">${escapeHtml(trigger.name)}</a>` : escapeHtml(trigger.name)}<div class="muted small">API Gateway · ${escapeHtml(trigger.kind)}</div><div class="muted small mono">${escapeHtml(trigger.sid)}</div></td><td><span class="status ${trigger.missing ? "inactive" : ""}">${trigger.missing ? "API not found" : "Enabled"}</span></td><td>–</td><td><span class="mono small">${escapeHtml(trigger.sourceArn || "Any API Gateway source")}</span>${trigger.endpoint ? `<div class="muted small mono">${escapeHtml(trigger.endpoint)}</div>` : ""}</td><td>Resource-based policy statement</td><td><button class="button link danger" data-delete-api-trigger="${escapeHtml(trigger.sid)}">Delete</button></td></tr>`).join("");
    const s3Rows = s3Triggers.map((trigger, index) => `<tr><td><a href="#/s3/buckets/${encodeURIComponent(trigger.bucket)}/properties">${escapeHtml(trigger.bucket)}</a><div class="muted small">S3 · bucket notification</div><div class="muted small mono">${escapeHtml(trigger.id)}</div></td><td><span class="status">Enabled</span></td><td>–</td><td>${escapeHtml(trigger.events.join(", "))}<div class="muted small mono">Prefix: ${escapeHtml(trigger.prefix || "*")} · Suffix: ${escapeHtml(trigger.suffix || "*")}</div></td><td>Asynchronous invocation</td><td><button class="button link danger" data-delete-s3-trigger="${index}">Delete</button></td></tr>`).join("");
    const eventBridgeRows = eventBridgeTriggers.map((trigger, index) => `<tr><td><a href="#/eventbridge/rules/${encodeURIComponent(trigger.bus)}/${encodeURIComponent(trigger.name)}">${escapeHtml(trigger.name)}</a><div class="muted small">EventBridge (CloudWatch Events) · ${escapeHtml(trigger.bus)} bus</div><div class="muted small mono">${escapeHtml(trigger.arn)}</div></td><td><span class="status ${trigger.state === "DISABLED" ? "inactive" : ""}">${escapeHtml(trigger.state === "DISABLED" ? "Disabled" : "Enabled")}</span></td><td>–</td><td>${trigger.schedule ? `Schedule: <span class="mono">${escapeHtml(trigger.schedule)}</span>` : `Event pattern: <span class="mono small">${escapeHtml(String(trigger.pattern || "").slice(0, 160))}</span>`}</td><td>Asynchronous invocation</td><td><button class="button link danger" data-delete-eventbridge-trigger="${index}">Delete</button></td></tr>`).join("");
    const snsRows = snsTriggers.map((trigger, index) => `<tr><td><a href="#/sns/topics/${encodeURIComponent(snsTopicName(trigger.topicArn))}">${escapeHtml(snsTopicName(trigger.topicArn))}</a><div class="muted small">SNS · topic subscription</div><div class="muted small mono">${escapeHtml(trigger.subscriptionArn)}</div></td><td><span class="status">Enabled</span></td><td>–</td><td><span class="mono small">${escapeHtml(trigger.topicArn)}</span></td><td>Asynchronous invocation</td><td><button class="button link danger" data-delete-sns-trigger="${index}">Delete</button></td></tr>`).join("");
    const triggerCount = mappings.length + apiTriggers.length + s3Triggers.length + eventBridgeTriggers.length + snsTriggers.length;
    const inventoryWarning = unavailableS3Buckets.length ? `<div class="alert warning card-inset"><strong>Partial S3 trigger inventory</strong><br>${unavailableS3Buckets.length} ${unavailableS3Buckets.length === 1 ? "bucket could" : "buckets could"} not be inspected with the current permissions or no longer exists.</div>` : "";
    const triggers = `<section class="card trigger-card"><div class="card-header"><div><h2>Triggers <span class="muted">(${triggerCount})</span></h2><p class="muted small">Event sources that invoke this function.</p></div><button class="button primary" data-action="add-trigger">Add trigger</button></div>${inventoryWarning}<div class="table-wrap">${triggerCount ? `<table><thead><tr><th>Source</th><th>State</th><th>Batch</th><th>Configuration</th><th>Last processing result</th><th>Actions</th></tr></thead><tbody>${rows}${apiRows}${s3Rows}${eventBridgeRows}${snsRows}</tbody></table>` : emptyState("↯", "No triggers", "Add an API Gateway, S3, EventBridge, SNS, DynamoDB stream, or SQS queue trigger to invoke this function.", '<button class="button primary" data-action="add-trigger">Add trigger</button>')}</div><div class="card-body"><div class="alert info">${deliveryGuidance}</div></div></section>`;
    const image = fn.PackageType === "Image"; const inlineSource = code.StackSimCodeSource?.Type === "Inline" ? code.StackSimCodeSource : undefined; const imageDetails = image ? `<div class="card image-code-card"><div class="card-header"><div><h2>Container image</h2><p class="muted small">Configured reference and immutable resolved digest.</p></div><button class="button" data-action="update-image-code">Deploy new image</button></div><div class="card-body"><div class="detail-grid"><dl class="key-value"><dt>Image URI</dt><dd class="mono">${escapeHtml(code.ImageUri)}</dd><dt>Resolved image URI</dt><dd class="mono">${escapeHtml(code.ResolvedImageUri)}</dd></dl><dl class="key-value"><dt>Local source mode</dt><dd>${escapeHtml(code.LocalImageSource || "Unavailable")}</dd><dt>Pinned digest</dt><dd>${code.LocalImageDigestSource === "image-id" ? '<span class="status pending">Local image ID</span><div class="muted small">No repository digest on the daemon; CodeSha256 derives from the local image ID, not a registry digest.</div>' : code.LocalImageDigestSource ? '<span class="status">Repository digest</span>' : "–"}</dd><dt>Architecture</dt><dd>${escapeHtml(fn.Architectures?.[0] || "x86_64")}</dd></dl></div><div class="alert warning"><strong>Explicit local dependency boundary</strong><br>The simulator never logs in to ECR, pulls from a registry, or downloads an image. OCI layouts are inspected and digest-pinned; invocation remains blocked unless the configured local source has a compatible isolated executor.</div></div></div>` : "";
    const sourceProperties = inlineSource ? `<dl class="key-value"><dt>Code source</dt><dd>Inline code</dd><dt>Source file</dt><dd class="mono">${escapeHtml(inlineSource.FileName)}</dd></dl>` : `<dl class="key-value"><dt>Package type</dt><dd>${escapeHtml(fn.PackageType === "Zip" ? "ZIP archive" : fn.PackageType)}</dd>${image ? "" : `<dt>Handler file</dt><dd class="mono">${escapeHtml(handlerFileCandidates(fn.Handler).join(" / "))}</dd>`}</dl>`;
